-- The Endocrine System — Batch 2 — Transport, Feedback & Hypothalamus/Pituitary
-- Original Praxist Prep questions, grounded in the subject reference textbook; scope verified vs AAMC 2026 outline.
-- Idempotent: deletes only this batch's subtopics, then re-inserts. question_attempts / distractor_metadata cascade.

DELETE FROM questions WHERE topic = 'The Endocrine System' AND subtopic IN ('Feedback & Neuroendocrine Integration', 'Hormone Transport, Specificity & Kinetics', 'Hypothalamus & Pituitary');

-- Q1 [Hormone Transport, Specificity & Kinetics] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'A lipophilic hormone circulates reversibly attached to a plasma protein, in equilibrium with a small fraction dissolved directly in plasma. A patient is given a drug that acutely doubles the plasma concentration of this binding protein. Before any change in glandular secretion occurs, what happens to the amount of hormone able to enter and act on target cells?', '[{"label": "A", "text": "It decreases transiently as more hormone binds protein"}, {"label": "B", "text": "It increases because total circulating hormone rises"}, {"label": "C", "text": "It is unaffected because total hormone is unchanged"}, {"label": "D", "text": "It increases because binding proteins deliver hormone into cells"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is A because only the small fraction of hormone that is unbound (free) in plasma can cross the lipid bilayer and enter target cells; the fraction reversibly bound to plasma transport protein cannot freely diffuse into cells and serves as a circulating reservoir. Acutely doubling the binding protein adds binding sites, so the equilibrium shifts toward the bound state and more hormone is captured, transiently lowering the free (active) hormone available to cells until secretory feedback compensates. (Choice A) is correct: adding transport-protein binding sites shifts the reversible binding equilibrium so a greater share of hormone is sequestered as bound, and the free hormone that can enter cells falls immediately, before the gland alters output. (Choice B) is incorrect: an acute rise in binding protein does not raise total secreted hormone before glandular compensation, and even a higher total does not increase the active pool, because it is the free fraction—not total—that enters cells; the added protein holds more hormone bound. (Choice C) is incorrect: although total hormone is momentarily unchanged, the biologically active pool is the unbound fraction, which is not fixed—shifting the binding equilibrium by adding carrier sites lowers it. (Choice D) is incorrect: transport proteins keep hormone in the blood and prevent its free diffusion into cells rather than ferrying it across the membrane; only the dissociated free hormone crosses on its own. This Skill 2 item requires reasoning from a perturbation of binding-site availability to its effect on the free active fraction, rather than recalling a definition.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 80, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'conflates total circulating hormone with the biologically active (free) fraction' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'correctly notes total hormone is unchanged but wrongly concludes the active pool is therefore fixed' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'treats the carrier protein as a delivery vehicle into cells rather than a reservoir that prevents free diffusion' FROM q;

-- Q2 [Hormone Transport, Specificity & Kinetics] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'A peptide hormone secreted into the blood reaches a person''s hepatocytes and adipocytes at identical concentrations, yet only the hepatocytes increase their glucose release in response. Which factor best explains why the adipocytes fail to respond?', '[{"label": "A", "text": "The hormone is too lipid-soluble to enter adipocytes"}, {"label": "B", "text": "Adipocytes lack the surface protein that binds this hormone"}, {"label": "C", "text": "Adipocytes release a hormone that opposes this signal"}, {"label": "D", "text": "Adipocytes convert the hormone into an inactive form"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is B because a hormone travels throughout the body in the bloodstream and reaches virtually every tissue, but it triggers a response only in cells that possess receptors specific to that hormone; since both cell types receive the hormone at equal concentrations, the selective response in hepatocytes must reflect that only hepatocytes express the receptor protein that binds this hormone, whereas adipocytes do not. (Choice B) is correct: target-tissue specificity is determined by receptor distribution, so cells lacking the matching receptor cannot initiate the signaling chain even when the hormone is present at the same concentration. (Choice A) is incorrect: this is a peptide hormone, which is lipid-insoluble and binds receptors on the outer surface of the plasma membrane rather than entering cells, so solubility-based entry is not the mechanism of tissue selectivity, and lipid solubility would not differ between two cell types anyway. (Choice C) is incorrect: an opposing (antagonistic) hormone released by adipocytes would modulate the magnitude of a response, not explain the complete absence of one, and the scenario provides no evidence of a second hormone; specificity is set by the receptor, not by a competing secretion. (Choice D) is incorrect: local inactivation would alter the hormone''s clearance, but the stem specifies that equal hormone concentrations reach both tissues, and inactivation of hormone after binding does not account for the lack of any initial response in a cell that never bound the hormone. This item requires Skill 2 reasoning: the student must interpret a scenario of equal delivery but unequal response and infer that differential receptor expression, not differences in delivery, solubility, competing hormones, or degradation, accounts for target-tissue specificity.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 80, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'confusing peptide (lipid-insoluble, surface-receptor) hormones with steroid hormones that diffuse into the cell' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'attributing absence of a response to an opposing/antagonistic hormone rather than to receptor absence' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'conflating local hormone inactivation/clearance with the receptor-binding step that determines whether a cell responds' FROM q;

-- Q3 [Hormone Transport, Specificity & Kinetics] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'Plasma is separated into a carrier-protein-bound fraction and a free, directly dissolved fraction, and several hormones are assayed for how they distribute between the two. Which hormone is recovered almost entirely in the free, directly dissolved fraction?', '[{"label": "A", "text": "Aldosterone"}, {"label": "B", "text": "Cortisol"}, {"label": "C", "text": "Glucagon"}, {"label": "D", "text": "Thyroxine"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.''

The answer is C because glucagon is a protein (peptide) hormone, and peptide hormones are water-soluble; they dissolve directly in the aqueous plasma and require no carrier protein, so glucagon is found overwhelmingly in the free fraction. Lipophilic hormones instead ride on transport proteins and appear in the bound fraction.

(Choice C) is correct: glucagon is a water-soluble protein hormone, so it circulates dissolved directly in plasma rather than bound to a carrier.

(Choice B) is incorrect: cortisol is a steroid hormone derived from cholesterol; being lipophilic, it is carried through the aqueous plasma bound to transport proteins, placing it in the bound fraction.

(Choice A) is incorrect: aldosterone is likewise a cholesterol-derived steroid hormone that is lipid-soluble and travels bound to plasma transport proteins, not free.

(Choice D) is incorrect: although thyroxine is an amine, it is lipid-soluble and circulates almost entirely bound to thyroxine-binding globulin and other plasma proteins, so it is recovered in the bound fraction.

This Skill 1 item asks the student to recall which hormone class is water-soluble and apply that to predict which hormone circulates free rather than protein-bound.', 'easy', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 1, 45, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'treats a lipophilic steroid as if it were water-soluble and carrier-free' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'treats a lipophilic steroid as if it circulated free' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'assumes an amine hormone is water-soluble, overlooking that thyroxine is lipophilic and carrier-bound' FROM q;

-- Q4 [Hormone Transport, Specificity & Kinetics] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'A drug binds thyroxine-binding globulin and displaces the thyroid hormone it was carrying, without altering hormone synthesis, degradation, or feedback within the first minute. Immediately after the drug acts, what is the effect on target-cell hormone activity?', '[{"label": "A", "text": "Increased, from raised transport-protein capacity"}, {"label": "B", "text": "Unchanged, since total hormone is constant"}, {"label": "C", "text": "Transiently decreased, from less free hormone"}, {"label": "D", "text": "Transiently increased, from more free hormone"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is D because only the free (unbound) fraction of a lipid-derived hormone can cross the target-cell membrane and exert biological effects; the protein-bound fraction is an inactive circulating reservoir. Displacing hormone off its transport protein shifts molecules from the bound pool into the free pool, so before feedback can compensate, the free concentration rises and target-cell activity transiently increases. (Choice D) is correct: because roughly 99% of circulating thyroid hormone is normally bound and less than 1% is free, releasing even a small bound fraction produces a proportionally large jump in free hormone, and free hormone is the species that enters cells and drives the response. (Choice B) is incorrect: total hormone (bound plus free) does indeed stay essentially constant in the first moment because nothing is synthesized or degraded, but total concentration is not what determines activity; the biologically active pool is the free fraction, which rises even while the total is unchanged, so reasoning from total hormone gives the wrong physiologic prediction. (Choice C) is incorrect: it reverses the relationship, treating displacement from the carrier as if it removed hormone from circulation; in fact displacement liberates hormone into the free pool and raises, rather than lowers, the active concentration. (Choice A) is incorrect: a drug that occupies and displaces hormone from the transport protein reduces the protein''s available hormone-carrying capacity rather than raising it, and increased binding capacity would sequester free hormone and lower activity, the opposite of the observed transient effect. In Skill 2 fashion, the item requires combining the fact that only free hormone is active with the reservoir behavior of the bound pool to predict the direction and transient nature of the physiologic change rather than recalling a definition.', 'hard', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 95, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'partial_truth', 'total-hormone-unchanged / conflating total with active fraction (510-tempting)' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'displacement misread as clearance, free hormone falls' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'transport-protein capacity raised rather than reduced by the displacing drug' FROM q;

-- Q5 [Hormone Transport, Specificity & Kinetics] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'A researcher adds excess purified thyroxine-binding globulin to a blood sample containing a fixed total quantity of a lipid-soluble hormone, then measures the hormone''s ability to enter and act on target cells. Compared with an untreated sample, the treated sample most likely shows which change in the hormone''s effect at target cells?', '[{"label": "A", "text": "Increased effect from higher total hormone"}, {"label": "B", "text": "Decreased effect, less hormone available"}, {"label": "C", "text": "No change; receptors bind bound hormone"}, {"label": "D", "text": "Increased effect via faster receptor turnover"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is B because only the free (unbound) fraction of a lipid-soluble hormone can diffuse across the target-cell membrane and engage its receptor; carrier proteins such as thyroxine-binding globulin bind hormone into an inactive circulating reservoir, and this ''packaging'' prevents free diffusion into cells. Adding excess carrier protein to a fixed total hormone pool shifts the equilibrium toward the bound state, lowering the free concentration, so fewer hormone molecules reach receptors and the effect at target cells falls. (Choice B) is correct: raising carrier-protein concentration sequesters more hormone as the inactive bound form, dropping the free (active) fraction and reducing hormone action on target cells. (Choice A) is incorrect: although added carrier protein can raise measured total hormone, bound hormone is not active, so total concentration does not predict effect; only the free fraction determines receptor engagement. (Choice C) is incorrect: hormone must dissociate from its transport protein before it can cross the membrane and bind receptor, so receptors do not act on carrier-bound hormone. (Choice D) is incorrect: carrier binding governs how much hormone is free to reach receptors, not the rate of receptor recycling; invoking receptor turnover misidentifies the controlling variable and predicts the wrong direction. Answering requires applying the free-versus-bound activity principle to a perturbation of carrier-protein levels rather than recalling a definition, consistent with a Skill 2 task.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'total-concentration-equals-activity' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'bound-hormone-is-active' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'wrong-controlling-variable' FROM q;

-- Q6 [Hormone Transport, Specificity & Kinetics] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'A researcher measures the plasma half-lives of two hormones in a patient: Hormone X falls to half its concentration in about 1 minute, while Hormone Y takes 60–90 minutes. Which conclusion about Hormone Y is best supported?', '[{"label": "A", "text": "It acts through a cell-surface receptor"}, {"label": "B", "text": "It is stored in secretory vesicles before release"}, {"label": "C", "text": "It circulates bound to a transport protein"}, {"label": "D", "text": "It is degraded rapidly by plasma enzymes"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is C because a half-life of 60–90 minutes marks Hormone Y as a lipid-derived (steroid) hormone: because steroids are hydrophobic and cannot dissolve freely in water-based blood, they travel bound to a transport protein, and this carrier-bound state shields them from degradation and renal filtration, extending the half-life far beyond that of amino acid–derived hormones. Hormone X''s ~1-minute half-life matches an amino acid–derived hormone such as epinephrine, which circulates free and is cleared almost immediately. (Choice C) is correct: transport-protein binding is precisely what protects a steroid hormone from rapid clearance and produces the long half-life observed for Hormone Y, so the 60–90 minute value is best explained by carrier-bound circulation. (Choice B) is incorrect: pre-secretion vesicular storage is characteristic of water-soluble peptide/amine hormones, and where a hormone is stored before release does not govern how quickly it is cleared once it is already circulating in plasma. (Choice A) is incorrect: signaling through a cell-surface (membrane) receptor is the hallmark of water-soluble hormones like the rapidly cleared Hormone X, whereas the long-lived steroid pattern of Hormone Y instead points toward intracellular receptor action. (Choice D) is incorrect: rapid enzymatic degradation would shorten, not lengthen, the half-life, so it describes the ~1-minute clearance of Hormone X and directly contradicts the 60–90 minute persistence of Hormone Y. Skill 2 is assessed because the student must translate quantitative clearance data into hormone class and then reason from that class to the underlying transport mechanism.', 'hard', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'adjacent_fact', 'vesicular storage of peptide hormones conflated with clearance kinetics' FROM q
  UNION ALL
  SELECT id, 'A', 'reversed_relationship', 'assigns water-soluble hormone''s membrane-receptor mechanism to the long-lived steroid' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'rapid enzymatic clearance mapped to long half-life instead of short' FROM q;

-- Q7 [Hormone Transport, Specificity & Kinetics] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hormone Transport, Specificity & Kinetics', 'Epinephrine, released from the adrenal medulla, dissolves in plasma and circulates freely to its targets. Cortisol, released from the adrenal cortex to regulate glucose metabolism, cannot circulate this way and must instead be carried bound to a plasma transport protein. Which property of cortisol most directly explains why it, unlike epinephrine, cannot travel freely dissolved in blood?', '[{"label": "A", "text": "Its shape is recognized by intracellular receptors"}, {"label": "B", "text": "It has an extremely short circulating half-life"}, {"label": "C", "text": "It cannot diffuse across the plasma membrane"}, {"label": "D", "text": "It is hydrophobic and poorly soluble in water"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is D because cortisol is a steroid hormone derived from the lipid cholesterol and, like cholesterol, is hydrophobic and not soluble in water; since blood is a water-based medium, a hydrophobic hormone cannot dissolve and travel freely in aqueous plasma and must instead be carried bound to a transport protein. Epinephrine, by contrast, is an amino-acid-derived (water-soluble) hormone, which is why it can circulate freely dissolved. (Choice D) is correct: steroid hormones are hydrophobic and poorly soluble in the aqueous plasma, so a transport protein is required to keep them in circulation. (Choice B) is incorrect: a longer half-life is a downstream consequence of being bound to a carrier, not the reason binding is required; in fact steroid hormones such as cortisol have relatively long half-lives (about 60 to 90 minutes), whereas it is epinephrine that has a very short half-life (about one minute), so a short half-life neither describes cortisol nor explains the need for a carrier. (Choice C) is incorrect: steroid hormones derived from cholesterol readily diffuse through the lipid bilayer of the cell membrane, so an inability to cross membranes is false and, in any case, concerns cellular entry rather than transport through plasma. (Choice A) is incorrect: shape recognition describes receptor specificity at the target cell, and although steroids do act through intracellular receptors, this addresses signaling at the target rather than why the hormone cannot travel free in blood. This question requires the student to identify the foundational solubility property that necessitates a carrier protein.', 'easy', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 1, 60, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses the consequence of carrier binding (extended half-life) with the cause; also misattributes a short half-life to cortisol when the short half-life belongs to the freely dissolved epinephrine' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'States a true-sounding claim about membrane crossing that is actually false for steroids and irrelevant to plasma transport' FROM q
  UNION ALL
  SELECT id, 'A', 'process_step_confusion', 'Confuses target-cell receptor specificity with the blood-transport step' FROM q;

-- Q8 [Feedback & Neuroendocrine Integration] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A patient begins taking a synthetic steroid that binds the same receptors as the adrenal cortex''s end-product hormone, sharply raising the effective level of that circulating signal. Weeks later, what happens to the hypothalamic releasing hormone and the pituitary trophic hormone that normally drive this axis?', '[{"label": "A", "text": "Both the releasing and trophic hormones fall"}, {"label": "B", "text": "Both the releasing and trophic hormones rise"}, {"label": "C", "text": "The releasing hormone falls; the trophic hormone rises"}, {"label": "D", "text": "The trophic hormone falls; the releasing hormone rises"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is A because in a classic negative feedback axis, a high level of the peripheral gland''s end-product hormone inhibits both the pituitary trophic hormone and the hypothalamic releasing hormone above it; a synthetic steroid mimicking the adrenal end-product is read by the brain and pituitary as elevated product, so both upstream signals are suppressed and fall together. (Choice A) is correct: as glucocorticoid-equivalent levels rise, the hypothalamus reduces its releasing hormone and the pituitary reduces its trophic hormone, because rising end-product concentration inhibits further signaling at both upstream tiers of the axis. (Choice B) is incorrect: a coordinated rise in both upstream hormones describes positive feedback, in which a product amplifies its own drivers; the adrenal axis is regulated by negative feedback, so elevated product suppresses, not stimulates, the upstream hormones. (Choice C) is incorrect: it correctly suppresses the hypothalamic releasing hormone but wrongly leaves the pituitary trophic hormone rising, whereas feedback from the elevated end-product inhibits the pituitary tier as well, so the trophic hormone also falls. (Choice D) is incorrect: it reverses the hypothalamic response, assuming the releasing hormone climbs to compensate; in negative feedback the elevated product inhibits the hypothalamus too, so the releasing hormone falls rather than rises. This item requires Skill 2 reasoning because the student must apply the directional logic of a multi-tier negative feedback axis to a novel pharmacologic perturbation, predicting the coordinated response of two upstream hormones rather than recalling any single hormone''s name.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'confusing negative feedback with positive feedback' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'believes only the hypothalamus senses feedback while the pituitary is unaffected' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'believes the hypothalamus compensates upward when the pituitary is inhibited' FROM q;

-- Q9 [Feedback & Neuroendocrine Integration] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A patient with a chronic inflammatory disorder takes high, sustained oral doses of a synthetic compound that binds the same intracellular receptors as the steroid normally secreted by the cortex of the glands capping the kidneys. After several months of therapy, blood levels of that synthetic compound remain persistently elevated. Which set of changes best describes this patient''s own regulatory axis?', '[{"label": "A", "text": "Releasing hormone rises; trophic hormone falls; gland atrophies"}, {"label": "B", "text": "Releasing and trophic hormones rise; native gland hypertrophies"}, {"label": "C", "text": "Releasing and trophic hormones fall; native gland atrophies"}, {"label": "D", "text": "Releasing and trophic hormones fall; native gland enlarges"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is C because the synthetic compound acts through the same receptors as the cortex-derived steroid (cortisol), so the body reads its persistently elevated blood level as an abundance of that end-product hormone. In the classic negative feedback loop of this axis, rising levels of the peripheral steroid inhibit both the hypothalamic releasing hormone (corticotropin-releasing hormone) and the anterior pituitary trophic hormone (adrenocorticotropic hormone, ACTH). Because ACTH normally stimulates the adrenal cortex to grow and secrete, the loss of that trophic stimulation causes the patient''s own peripheral gland to shrink (atrophy) from disuse. Thus both upstream hormones fall and the native gland atrophies. (Choice C) is correct: exogenous end-product hormone suppresses the releasing hormone and the trophic hormone via negative feedback, and withdrawal of trophic support atrophies the peripheral gland. (Choice B) is incorrect: rising upstream hormones and gland hypertrophy would occur if the peripheral steroid were deficient (as in primary gland failure), which triggers up-regulation of the axis, not from supraphysiologic exogenous hormone. (Choice A) is incorrect: it correctly predicts gland atrophy and a falling trophic hormone but wrongly claims the hypothalamic releasing hormone rises; negative feedback from the elevated steroid suppresses both upstream hormones, not just the pituitary one. (Choice D) is incorrect: it correctly predicts that both upstream hormones fall, but a gland deprived of its trophic stimulus shrinks rather than enlarges; enlargement requires sustained trophic drive. Skill 2: this item requires integrating the direction of feedback across three sequential compartments of a neuroendocrine axis and predicting a structural consequence (atrophy) from a functional change (loss of trophic signaling), rather than recalling a single definition.', 'hard', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 95, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses exogenous excess with endogenous deficiency, reversing the direction of feedback so the axis is upregulated' FROM q
  UNION ALL
  SELECT id, 'A', 'partial_truth', 'Correctly suppresses the pituitary trophic hormone and atrophies the gland but fails to extend feedback suppression to the hypothalamic releasing hormone' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Correctly suppresses both upstream hormones but mispredicts the structural fate of a gland deprived of trophic stimulation' FROM q;

-- Q10 [Feedback & Neuroendocrine Integration] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'During labor, stretch of the cervix signals the pituitary to secrete a hormone that strengthens uterine contractions, which stretch the cervix still further and evoke yet more of that same hormone. Based on this loop''s structure, how will hormone secretion behave once contractions begin?', '[{"label": "A", "text": "Falls as the response reverses the stretch"}, {"label": "B", "text": "Is suppressed once levels become adequate"}, {"label": "C", "text": "Oscillates around a fixed set point"}, {"label": "D", "text": "Escalates progressively until delivery ends it"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is D because the loop described is a positive feedback system: the hormone''s own action (stronger contractions) intensifies the original stimulus (cervical stretch), which drives release of still more hormone, so secretion is self-reinforcing and accelerates rather than being opposed. Such a loop moves the system progressively farther from its starting state until a definite end point—delivery of the infant—removes the stimulus and halts release. (Choice D) is correct: in positive feedback the product amplifies the very change that triggered it, producing a runaway surge that continues to escalate until an external endpoint interrupts the cycle. (Choice B) is incorrect: suppression of further secretion once a hormone reaches an adequate blood level defines negative feedback, the opposite arrangement, which stabilizes rather than amplifies output. (Choice C) is incorrect: maintaining a variable near a fixed set point by correcting deviations is the behavior of a negative-feedback homeostatic loop, not of a self-amplifying cascade that has no stabilizing set point. (Choice A) is incorrect: a response that reverses its own triggering stimulus opposes the initial change and thereby restores the resting state, which is again negative feedback and contradicts the amplifying structure described. Recognizing this requires Skill 2 reasoning: the student must analyze the causal chain in the scenario, infer that action feeds back to amplify its own cause, and predict the resulting escalating behavior rather than recall a definition.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confusing positive feedback with negative feedback''s inhibition of further secretion at adequate levels' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Assuming all endocrine feedback defends a fixed set point (homeostatic set-point overgeneralization)' FROM q
  UNION ALL
  SELECT id, 'A', 'reversed_relationship', 'Treating the loop as opposing/reversing its stimulus (negative feedback direction) rather than amplifying it' FROM q;

-- Q11 [Feedback & Neuroendocrine Integration] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A researcher continuously monitors a metabolic-rate hormone in a healthy animal. Over several hours its blood concentration climbs well above the midpoint of its normal range while every regulatory pathway stays intact. What most likely happens to the upstream signal that drives this hormone''s synthesis?', '[{"label": "A", "text": "Its release is suppressed"}, {"label": "B", "text": "Its release is amplified further"}, {"label": "C", "text": "Its release stays exactly constant"}, {"label": "D", "text": "Its release rises to match demand"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is A because negative feedback is characterized by the inhibition of further secretion of a hormone once blood levels of that hormone become adequate; when the regulated metabolic hormone climbs above the middle of its range, the upstream stimulating signal (such as TRH/TSH driving thyroid hormone) is suppressed, holding the hormone within a narrow range and maintaining homeostasis. (Choice A) is correct: high levels of the regulated hormone act back on the hypothalamus and pituitary to decrease production and secretion of the stimulating signal, reversing the deviation from the set point. (Choice B) is incorrect: amplification of the driving signal describes positive feedback, such as oxytocin during labor, which pushes a parameter further from homeostasis rather than restraining a hormone that is already high. (Choice C) is incorrect: an unchanging upstream signal would let the hormone drift ever higher, which is not how a homeostatic negative feedback loop behaves when levels exceed the set point. (Choice D) is incorrect: increasing the driving signal when the hormone is already elevated would worsen the deviation; feedback loops change the direction of the stimulus rather than raise output to meet demand. This item assesses Skill 1 by asking the student to recall and identify the direction of the negative feedback response when a regulated hormone is already high.', 'easy', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 1, 60, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'confuses negative feedback with positive feedback amplification' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'treats feedback as maintaining a fixed signal rather than adjusting it' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'predicts output rises to meet demand rather than being shut off' FROM q;

-- Q12 [Feedback & Neuroendocrine Integration] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A patient undergoes complete surgical removal of the gland whose hormones set the body''s basal metabolic rate, and no hormone replacement is given. Six weeks later, clinicians measure the anterior pituitary hormone that had regulated that gland. What is the expected result?', '[{"label": "A", "text": "Thyroid-stimulating hormone is suppressed"}, {"label": "B", "text": "Thyroid-stimulating hormone is elevated"}, {"label": "C", "text": "Adrenocorticotropic hormone is elevated"}, {"label": "D", "text": "Triiodothyronine is elevated"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is B because the removed gland is the thyroid, whose hormones (T3 and T4) normally exert negative feedback on the anterior pituitary; losing that gland eliminates the circulating hormone, removing the inhibition, so the pituitary trophic hormone that stimulated the thyroid rises. (Choice B) is correct: with the thyroid gone, blood T3 and T4 fall to near zero, and because increasing levels of T3 and T4 normally decrease TSH secretion, the loss of that feedback disinhibits the anterior pituitary and thyroid-stimulating hormone climbs. (Choice A) is incorrect: suppression would occur only if the missing hormone had provided positive feedback; treating the loss of an inhibitory signal as if it lowered TSH reverses the direction of a classic negative feedback loop, the tempting error near the 510 threshold. (Choice C) is incorrect: adrenocorticotropic hormone stimulates the adrenal cortex, not the thyroid, and its secretion is governed by glucocorticoid feedback, which is unaffected by thyroid removal. (Choice D) is incorrect: triiodothyronine is the peripheral thyroid hormone itself, which is eliminated by the surgery and cannot rise, and it is not an anterior pituitary product as the question requires. To reason to the answer, a student must identify the axis from the gland''s function, recognize which pituitary hormone regulated it, and predict the feedback consequence of removing the peripheral hormone.', 'hard', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Treats loss of an inhibitory signal as if the feedback were positive, so the trophic hormone is predicted to fall' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Correct direction but wrong endocrine axis; confuses the HPA (adrenal) axis with the HPT (thyroid) axis' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'Names the eliminated peripheral hormone instead of the pituitary trophic hormone, confusing steps of the axis' FROM q;

-- Q13 [Feedback & Neuroendocrine Integration] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A frightened rodent shows a rapid surge in blood epinephrine. Emotional-processing centers of the forebrain, such as the amygdala, send neural projections that converge on a single brain structure; that structure then sends descending sympathetic output which ultimately reaches the gland whose cells secrete the epinephrine. Which structure receives the forebrain projections and directs the sympathetic outflow that produces this endocrine surge?', '[{"label": "A", "text": "Adrenal medulla"}, {"label": "B", "text": "Posterior pituitary"}, {"label": "C", "text": "Anterior pituitary"}, {"label": "D", "text": "Hypothalamus"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' (Choice A) is incorrect: the adrenal medulla is the effector gland at the far end of the pathway. Its chromaffin cells are postganglionic sympathetic neurons that secrete epinephrine when they receive preganglionic sympathetic input, so the adrenal medulla is the output the pathway acts on, not the structure that receives the forebrain projections; per OpenStax A&P 2e the secretion of medullary epinephrine ''is controlled by a neural pathway that originates from the hypothalamus in response to danger or stress (the SAM pathway).'' (Choice D) is correct: the amygdala and other forebrain emotional centers project to the hypothalamus through the medial forebrain bundle, and the hypothalamus is the control center that then drives the descending sympathetic outflow reaching the adrenal medulla, so it is the structure that both receives the forebrain input and directs the sympathetic response that produces the epinephrine surge. (Choice C) is incorrect: the anterior pituitary secretes its hormones only in response to releasing hormones delivered from the hypothalamus through the hypophyseal portal system, so it sits downstream of the hypothalamus and receives no direct forebrain neural projections in this pathway. (Choice B) is incorrect: the posterior pituitary does not produce hormones; it only stores and releases peptides made by hypothalamic neurons and is not the structure that receives forebrain input or directs the sympathetic outflow to the adrenal medulla. Answering requires tracing the fight-or-flight pathway from forebrain emotional centers to the sympathetic effector and identifying the control structure in between, applying the principle that the hypothalamus links the nervous and endocrine systems to a novel scenario rather than recalling a stated definition.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'process_step_confusion', 'confusing the terminal effector gland with the upstream control structure that directs the sympathetic outflow' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'treating the downstream master gland as the structure that receives direct forebrain neural input' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'mistaking a hormone storage/release interface for the control center that directs the sympathetic response' FROM q;

-- Q14 [Feedback & Neuroendocrine Integration] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A patient has a cortical mass that continuously releases a steroid hormone regardless of upstream signals. Assays confirm a markedly elevated blood level of this steroid. Which pattern best describes the anterior pituitary tropic hormone and the hypothalamic releasing hormone that normally drive this steroid''s secretion?', '[{"label": "A", "text": "Both are suppressed below normal"}, {"label": "B", "text": "Both are elevated above normal"}, {"label": "C", "text": "Tropic elevated, releasing hormone suppressed"}, {"label": "D", "text": "Tropic suppressed, releasing hormone elevated"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is A because the mass secretes the peripheral steroid autonomously, so the high circulating steroid drives negative feedback onto both the anterior pituitary and the hypothalamus, shutting down the tropic hormone (ACTH) and the releasing hormone (CRH) that would normally stimulate the gland; the elevated end product itself, not upstream signaling, sustains secretion. (Choice A) is correct: with an autonomous peripheral source, the classic negative feedback loop senses the elevated steroid and inhibits secretion at both the pituitary (tropic) and hypothalamic (releasing) levels, yielding low values at both, which is the hallmark distinguishing a peripheral autonomous source from a central cause. (Choice B) is incorrect: both hormones being high would describe a pituitary-driven (tropic-excess) or hypothalamic-driven process in which the upstream signal is the cause of the excess; here the peripheral gland is the autonomous source, so feedback suppresses the upstream hormones rather than elevating them. (Choice C) is incorrect: an elevated tropic hormone with a suppressed releasing hormone would indicate an autonomous pituitary source overriding the hypothalamus, but the mass in this scenario is a peripheral gland below the pituitary, so the tropic hormone is suppressed, not elevated. (Choice D) is incorrect: a suppressed tropic hormone with an elevated releasing hormone is internally inconsistent with negative feedback, because a high circulating steroid inhibits the hypothalamus as well, so the releasing hormone cannot remain elevated when the peripheral steroid is high. Skill 2 is exercised because the student must integrate the direction of negative feedback with the anatomical level of the autonomous source to predict the specific high/low pattern across two upstream hormones rather than recall a single definition.', 'hard', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Assumes high peripheral hormone reflects high upstream drive, ignoring that autonomous secretion inverts the feedback relationship' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'Confuses the anatomical level of the autonomous source, treating a peripheral-gland tumor as if it were a pituitary (tropic) source' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Correctly suppresses the tropic hormone but fails to apply feedback to the hypothalamic releasing hormone as well' FROM q;

-- Q15 [Feedback & Neuroendocrine Integration] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Feedback & Neuroendocrine Integration', 'A patient on a several-week course of a synthetic glucocorticoid maintains plasma corticosteroid activity well above the physiologic set point. Assuming an intact regulatory axis, what happens to the hypothalamic releasing hormone and the anterior-pituitary trophic hormone that normally drive the adrenal cortex?', '[{"label": "A", "text": "CRH decreases but ACTH rises"}, {"label": "B", "text": "Both CRH and ACTH decrease"}, {"label": "C", "text": "Both CRH and ACTH increase"}, {"label": "D", "text": "CRH rises but ACTH decreases"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Mechanisms of Hormone Action.'' The answer is B because the hypothalamic-pituitary-adrenal axis is governed by negative feedback: corticotropin-releasing hormone (CRH) from the hypothalamus drives adrenocorticotropic hormone (ACTH) release from the anterior pituitary, which drives cortisol secretion from the adrenal cortex; when corticosteroid activity rises above the set point, the elevated glucocorticoid signal inhibits both the hypothalamus and the pituitary, so CRH and ACTH both fall. (Choice B) is correct: a synthetic glucocorticoid sustains a supraphysiologic corticosteroid signal that the hypothalamus and pituitary read as excess, and both structures reduce their signaling to the adrenal gland, lowering CRH and ACTH together. (Choice A) is incorrect: this treats the two upstream signals as independently regulated, but ACTH is released only in response to CRH, so suppression of CRH cannot coincide with a rise in ACTH under an intact axis. (Choice C) is incorrect: increased CRH and ACTH would be the response to a deficit of corticosteroid activity, not an excess; here the signal is elevated, so a positive-feedback-style increase reverses the actual direction of the loop. (Choice D) is incorrect: negative feedback from elevated glucocorticoid acts on both the hypothalamus and the pituitary, so CRH does not rise while ACTH falls; the hypothalamus and pituitary reduce their signaling together, meaning CRH cannot increase when the corticosteroid signal is supraphysiologic. In Skill 2 fashion, the item requires applying the negative-feedback structure of the HPA axis to predict the coordinated response of two upstream signals rather than recalling a single definition.', 'medium', '3A', 'Endocrine System: Mechanisms of Hormone Action', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'partial_truth', 'Applies feedback to the releasing hormone but wrongly treats the trophic hormone as independent, missing that ACTH depends on CRH' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Reverses the direction of negative feedback, predicting the deficit-state response (increase) to a corticosteroid excess' FROM q
  UNION ALL
