-- Q16 [Hypothalamus & Pituitary] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'Destroying the small blood vessels that run between the hypothalamus and the anterior pituitary halts secretion of the anterior pituitary''s hormones, yet the posterior pituitary keeps releasing its hormones normally. By what route does the hypothalamus normally control the anterior pituitary?', '[{"label": "A", "text": "Direct diffusion across a membrane shared by the two structures"}, {"label": "B", "text": "Axons that release the hormones directly into the lobe"}, {"label": "C", "text": "Releasing hormones carried through a portal blood system"}, {"label": "D", "text": "The ordinary systemic circulation, as for any distant gland"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.''

The answer is C because the hypothalamus secretes releasing hormones into the hypophyseal portal system, a dedicated set of blood vessels that carries them straight to the anterior pituitary without first entering the systemic circulation; destroying those vessels therefore cuts off anterior-pituitary control. The posterior pituitary is controlled by a different route (neurons), so it is unaffected.

(Choice C) is correct: the hypothalamus reaches the anterior pituitary hormonally, through the hypophyseal portal vessels, so severing those vessels abolishes anterior-pituitary secretion.

(Choice B) is incorrect: axonal release describes how the hypothalamus controls the POSTERIOR pituitary, whose ADH and oxytocin travel down neuronal axons; this is why the posterior lobe still functions after the vessels are cut.

(Choice A) is incorrect: the two structures are not linked by a shared membrane for diffusion; the functional connection to the anterior lobe is vascular.

(Choice D) is incorrect: the portal system specifically bypasses the systemic circulation, delivering hypothalamic hormones locally rather than through the general bloodstream.

This Skill 2 item requires interpreting the selective loss of anterior (but not posterior) secretion and inferring the vascular portal route the hypothalamus uses for the anterior pituitary.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'assigns the posterior pituitary''s neural/axonal control mechanism to the anterior pituitary' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'imagines direct membrane diffusion rather than a vascular connection' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'treats the private portal route as ordinary systemic delivery' FROM q;

-- Q17 [Hypothalamus & Pituitary] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'The hypothalamus empties its regulatory hormones into a dedicated portal circulation that carries them straight to the anterior pituitary rather than letting them mix into the general bloodstream first. What advantage does this private portal route provide?', '[{"label": "A", "text": "The hormones reach the pituitary at high concentration before systemic dilution"}, {"label": "B", "text": "The hormones travel faster than a nerve impulse could"}, {"label": "C", "text": "The hormones avoid being filtered out by the kidneys"}, {"label": "D", "text": "The route prevents negative feedback from reaching the hypothalamus"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.''

The answer is A because the hypophyseal portal vessels carry hypothalamic releasing hormones directly to the anterior pituitary without first entering the systemic circulation, so the hormones arrive at far higher local concentrations than they would after being diluted throughout the entire blood volume.

(Choice A) is correct: delivering the hormones locally before systemic dilution lets tiny amounts act potently on the anterior pituitary.

(Choice B) is incorrect: portal transport is carried by blood flow and is not faster than neural signaling; speed relative to nerves is not the reason a portal system exists.

(Choice C) is incorrect: escaping renal filtration is not the purpose; the portal simply routes the hormones to their target before any systemic distribution occurs.

(Choice D) is incorrect: negative feedback still operates on the hypothalamic-pituitary axis, so the portal does not shield the hypothalamus from feedback.

This Skill 2 item asks the student to reason about why a local portal circulation is advantageous, distinguishing concentrated local delivery from unrelated rationales.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'assumes a vascular portal outruns neural signaling and that speed is its purpose' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'invokes renal filtration, unrelated to the portal''s local-delivery function' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'assumes the portal blocks feedback, which still operates on the axis' FROM q;

-- Q18 [Hypothalamus & Pituitary] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'A researcher studies a peptide, hormone X, secreted by the anterior pituitary. When the anterior pituitary is removed, one particular endocrine gland shrinks and the amount of that gland''s own hormone in the blood falls to nearly zero; administering purified hormone X restores that gland''s size and hormone output. The researcher also finds that raising the downstream gland''s hormone experimentally causes the blood level of hormone X to drop. Which conclusion about how hormone X produces its effect is best supported by these observations?', '[{"label": "A", "text": "It acts directly on peripheral tissues such as skeletal muscle and bone to build them"}, {"label": "B", "text": "Its target is a second endocrine gland, which it drives to secrete that gland''s own hormone"}, {"label": "C", "text": "It raises the downstream hormone by blocking that hormone''s breakdown in the bloodstream"}, {"label": "D", "text": "It is enzymatically converted into the downstream gland''s hormone after being secreted"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because the data point to a tropic (tropho-) hormone: removing the pituitary makes a specific downstream endocrine gland atrophy and its own hormone plummet, re-administering hormone X restores that gland and its output, and raising the downstream hormone suppresses hormone X (negative feedback). Together these show hormone X''s target is another endocrine gland whose hormone secretion it stimulates—exactly how anterior-pituitary tropic hormones (TSH, ACTH, FSH, LH) work, turning the function of other endocrine glands on or off rather than acting on a final peripheral tissue. (Choice B) is correct: the gland-specific atrophy on removal, restoration on replacement, and feedback suppression establish that hormone X drives a second endocrine gland to release its own hormone—the defining behavior of a tropic hormone. (Choice A) is incorrect: direct action on muscle and bone describes growth hormone, a non-tropic anterior-pituitary hormone; it also contradicts the data, since it is a downstream gland (not muscle or bone) that atrophies and whose hormone is restored by hormone X. (Choice C) is incorrect: hormone X restores the downstream gland''s own hormone output and is itself shut off by that hormone, which reflects stimulated secretion by the gland, not slowed breakdown of an already-present hormone in the blood. (Choice D) is incorrect: a tropic hormone is not a precursor converted into the target gland''s hormone; the gland remains necessary (it atrophies when unstimulated), showing hormone X acts on the gland to make it secrete its own, chemically distinct hormone rather than becoming that hormone. Reaching Choice B requires integrating the ablation, replacement, and feedback data to infer the tropic mechanism rather than recalling a definition, exercising Skill 2 scientific reasoning.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'assumes an anterior-pituitary hormone acts directly on peripheral tissue like muscle and bone (growth hormone)' FROM q
  UNION ALL
