-- Q19 [Hypothalamus & Pituitary] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'A hiker who has gone many hours without water begins producing only a small volume of highly concentrated urine as the body conserves fluid. Increased secretion of which hormone is most directly responsible for this response?', '[{"label": "A", "text": "Atrial natriuretic peptide from the heart"}, {"label": "B", "text": "Aldosterone from the adrenal cortex"}, {"label": "C", "text": "Antidiuretic hormone from the posterior pituitary"}, {"label": "D", "text": "Renin from the kidneys"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because dehydration raises blood osmolarity, which hypothalamic osmoreceptors detect and signal the posterior pituitary to release antidiuretic hormone (ADH); ADH increases the water permeability of the kidney''s tubular (collecting duct) cells, driving water reabsorption back into the blood and yielding a small volume of concentrated urine. (Choice C) is correct: ADH is the hormone that directly increases renal water reabsorption, conserving body water and concentrating the urine, exactly the response described. (Choice B) is incorrect: aldosterone, a mineralocorticoid from the adrenal cortex, primarily promotes Na+ reabsorption (with water following) rather than directly controlling water permeability of the collecting ducts, so it is not the most direct driver of the concentrated-urine response to dehydration. (Choice A) is incorrect: atrial natriuretic peptide is released by the heart in response to high blood volume and promotes Na+ and water excretion, which would increase, not decrease, urine output, the opposite of the described conservation. (Choice D) is incorrect: renin is an enzyme released by the kidneys that initiates the renin-angiotensin-aldosterone cascade; it is not itself the hormone that directly increases collecting-duct water reabsorption. This item assesses Skill 1 by requiring recall of which hormone and source directly govern renal water conservation.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 55, NULL)
  RETURNING id
)
