-- Q20 [Hypothalamus & Pituitary] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'During nursing, an infant''s suckling triggers a neuroendocrine reflex that contracts the myoepithelial cells surrounding the mammary alveoli, forcing already-synthesized milk into the ducts. Which hormone directly mediates this ejection reflex?', '[{"label": "A", "text": "Progesterone"}, {"label": "B", "text": "Prolactin"}, {"label": "C", "text": "Antidiuretic hormone"}, {"label": "D", "text": "Oxytocin"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the milk ejection (letdown) reflex is driven by oxytocin: suckling generates afferent signals to the hypothalamus, which triggers oxytocin release from the posterior pituitary, and oxytocin causes the myoepithelial cells around the mammary alveoli to contract, forcing stored milk into the ducts. (Choice D) is correct: oxytocin is the posterior-pituitary hormone that contracts myoepithelial (smooth-muscle-like) cells to eject milk, exactly the event described. (Choice B) is incorrect: prolactin, from the anterior pituitary, stimulates the synthesis of milk by the alveolar cells, but it does not contract myoepithelial cells to eject the milk that has already been made; the stem specifies ejection of already-synthesized milk, not its production. (Choice C) is incorrect: antidiuretic hormone (vasopressin) is released from the same posterior pituitary but acts to promote water reabsorption in the kidney and vasoconstriction, not myoepithelial contraction or milk ejection. (Choice A) is incorrect: progesterone, a steroid from the ovary/placenta, primes mammary tissue during pregnancy and suppresses lactation before birth, but it does not mediate the acute suckling-triggered ejection reflex. Skill 2 is assessed here because the student must map the described physiological mechanism (reflexive contraction of myoepithelial cells ejecting stored milk) onto the specific hormone responsible, distinguishing milk ejection from milk production and distinguishing among hormones that share a source or a general reproductive role.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
