-- Q21 [Hypothalamus & Pituitary] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'A 9-year-old is evaluated for a height far above the normal range for their age, together with radiographs showing accelerated lengthening of the long bones at the epiphyseal plates. Chronic oversecretion of which hormone best accounts for this phenotype?', '[{"label": "A", "text": "Thyroxine"}, {"label": "B", "text": "Somatotropin"}, {"label": "C", "text": "Insulin-like growth factor 1"}, {"label": "D", "text": "Prolactin"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because somatotropin—the anterior pituitary hormone also called growth hormone (GH)—directly promotes protein synthesis in skeletal muscle and bone and triggers chondrocyte proliferation at the epiphyseal plates, so abnormally large amounts secreted during childhood cause the excessive linear bone growth seen in gigantism. (Choice B) is correct: gigantism is a childhood disorder caused by secretion of abnormally large amounts of GH (somatotropin), producing exactly the tall stature and accelerated long-bone lengthening described. (Choice A) is incorrect: thyroxine does stimulate bone growth and bone-matrix synthesis, but it is secreted by the thyroid gland and its excess produces a hypermetabolic state (elevated heat production and metabolic rate), not the pituitary-driven gigantism phenotype of markedly excessive skeletal elongation. (Choice C) is incorrect: insulin-like growth factor 1 is the liver-derived mediator through which GH acts indirectly; it is downstream of the pituitary hormone whose oversecretion is the primary cause, so it is the effector rather than the root hormone whose excess defines this disorder. (Choice D) is incorrect: prolactin is also an anterior pituitary hormone, but its function is to promote milk production by the mammary glands, and its excess is not associated with excessive skeletal growth. This item assesses Skill 1 by requiring recall of the source and childhood-excess consequence of an anterior pituitary hormone.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 60, NULL)
  RETURNING id
)
