-- Q22 [Hypothalamus & Pituitary] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'A patient suffers a head injury that severs the pituitary stalk, cutting the vascular link between the hypothalamus and the anterior pituitary. Over the following weeks, blood levels of most anterior-pituitary hormones fall, yet one anterior-pituitary hormone instead rises, and the patient begins producing breast milk. Which secreted product increases?', '[{"label": "A", "text": "Oxytocin"}, {"label": "B", "text": "Thyroid-stimulating hormone"}, {"label": "C", "text": "Prolactin"}, {"label": "D", "text": "Adrenocorticotropic hormone"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because most anterior-pituitary hormones require a stimulating (releasing) hormone delivered from the hypothalamus through the hypophyseal portal system, so severing the stalk causes their levels to fall; the one exception is regulated by tonic inhibition rather than stimulation. In the non-pregnant state, the hypothalamus continuously suppresses this hormone via prolactin-inhibiting hormone, which is the neurotransmitter dopamine. Removing that inhibitory input releases the anterior pituitary from suppression, so the hormone rises and stimulates the mammary glands to produce milk (galactorrhea). (Choice C) is correct: prolactin is the sole anterior-pituitary hormone under net inhibitory hypothalamic control (dopamine/PIH), so loss of the portal connection removes its brake and secretion increases, explaining the inappropriate milk production. (Choice B) is incorrect: thyroid-stimulating hormone secretion depends on thyrotropin-releasing hormone arriving via the portal system, so cutting the stalk removes its stimulus and TSH levels fall, not rise. (Choice A) is incorrect: oxytocin is synthesized in the hypothalamus and released from the posterior pituitary (it is not an anterior-pituitary product), and it drives milk let-down rather than milk synthesis; the question specifies an anterior-pituitary hormone whose level rises. (Choice D) is incorrect: adrenocorticotropic hormone requires corticotropin-releasing hormone from the hypothalamus, so loss of the portal delivery route causes ACTH to fall, consistent with the general pattern rather than the exception. To answer, a test-taker must integrate the mechanism of stalk section with the direction of each hormone''s hypothalamic control, recognizing that a hormone under tonic inhibition responds to disconnection in the opposite direction from stimulated hormones.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 100, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Assumes every anterior-pituitary hormone behaves identically; expects a stimulated hormone (TSH) to rise when its releasing signal is actually removed' FROM q
  UNION ALL
  SELECT id, 'A', 'adjacent_fact', 'Associates milk production with oxytocin (let-down) and ignores that oxytocin is a posterior-pituitary, hypothalamic-origin hormone, not an anterior-pituitary secretion' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Treats ACTH as an exception or stress-driven riser without recognizing it depends on CRH delivered through the severed portal system' FROM q;

-- Q23 [Hypothalamus & Pituitary] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'During prolonged psychological stress, a hypothalamic peptide is secreted that drives the anterior pituitary to release a tropic hormone. This tropic hormone acts on the outer region of the adrenal glands, promoting the catabolism of glycogen, triglycerides, and muscle protein to sustain blood glucose. Which anterior-pituitary hormone is responsible for this effect?', '[{"label": "A", "text": "Growth hormone"}, {"label": "B", "text": "Thyroid-stimulating hormone"}, {"label": "C", "text": "Luteinizing hormone"}, {"label": "D", "text": "Adrenocorticotropic hormone"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the hypothalamic peptide secreted during prolonged stress is corticotropin-releasing hormone, which triggers the anterior pituitary to release adrenocorticotropic hormone (ACTH); ACTH stimulates the adrenal cortex to secrete glucocorticoids such as cortisol, whose catabolism of glycogen, triglycerides, and muscle protein maintains fuel supplies. (Choice D) is correct: ACTH is the anterior-pituitary tropic hormone that acts on the adrenal cortex, and its downstream product cortisol produces exactly the described breakdown of stored nutrients under long-term stress. (Choice B) is incorrect: thyroid-stimulating hormone acts on the thyroid gland to release T3 and T4, not on the adrenal cortex, and is controlled by thyrotropin-releasing hormone rather than a stress-linked hypothalamic peptide. (Choice C) is incorrect: luteinizing hormone is a gonadotropin that acts on the gonads to trigger ovulation and steroid production, controlled by gonadotropin-releasing hormone, so it does not drive adrenal glucocorticoid release. (Choice A) is incorrect: growth hormone promotes tissue growth and is released in response to growth hormone-releasing hormone; although it influences metabolism, it does not act through the adrenal cortex to mobilize fuels in the stress response. This is a Skill 2 item because the student must reason backward from a described physiological effect and target gland to identify the specific hypothalamic-pituitary axis, rather than recall a stated definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'adjacent_fact', 'wrong hypothalamic-pituitary axis (thyroid axis substituted for adrenal axis)' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'wrong hypothalamic-pituitary axis (gonadal axis substituted for adrenal axis)' FROM q
  UNION ALL
