-- Q24 [Hypothalamus & Pituitary] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'During neurosurgery, the fine network of blood vessels bridging the hypothalamus and the pituitary gland is inadvertently severed, while the nerve fibers descending through the stalk remain intact. Secretion of one lobe''s hormones drops sharply. Which structure has lost its regulatory input?', '[{"label": "A", "text": "The anterior pituitary lobe"}, {"label": "B", "text": "The posterior pituitary lobe"}, {"label": "C", "text": "The hypothalamic neurons themselves"}, {"label": "D", "text": "The adrenal cortex"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the anterior pituitary manufactures its own hormones but secretes them only in response to releasing and inhibiting hormones that travel from the hypothalamus through a bridge of capillaries (the hypophyseal portal system) rather than through nerves; severing that vascular link cuts off its blood-borne regulatory signal, so its output falls even though the neural fibers are untouched. (Choice A) is correct: control of this lobe is hormonal and blood-borne, so destroying the portal capillaries removes the only pathway by which hypothalamic releasing/inhibiting hormones reach it, sharply reducing secretion. (Choice B) is incorrect: the posterior lobe stores and releases two hormones made by hypothalamic neurons and is triggered by direct neural signaling along axons in the stalk, so with the nerve fibers intact its release would continue despite the vascular injury. (Choice C) is incorrect: the hypothalamic neurons remain the source of the signals and are not downstream of the severed vessels; their synthesis of releasing hormones is unaffected by cutting the capillary bridge. (Choice D) is incorrect: the adrenal cortex is a peripheral target organ two steps removed from the stalk, and any change in its output would be an indirect downstream consequence rather than a loss of regulatory input at the site described. Skill 2: this item requires reasoning from a described perturbation—vascular versus neural control of two lobes—to assign the affected structure rather than recalling a definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses neural control (posterior) with hormonal/portal control (anterior)' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'Places the source neuron downstream of the severed vessels instead of upstream' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Selects a peripheral tropic target instead of the directly regulated lobe' FROM q;

-- Q25 [Hypothalamus & Pituitary] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Hypothalamus & Pituitary', 'A patient sustains a focal injury that destroys the neural storage-and-release terminals at the base of the infundibulum while completely sparing the glandular lobe that secretes tropic hormones. Which paired deficit is the direct consequence of this lesion?', '[{"label": "A", "text": "Failure of growth hormone and prolactin release"}, {"label": "B", "text": "Loss of cortisol and thyroid hormone secretion"}, {"label": "C", "text": "Impaired water reabsorption and milk let-down"}, {"label": "D", "text": "Absent aldosterone and epinephrine output"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because the destroyed structure is the posterior pituitary (neurohypophysis), which does not synthesize hormones but only stores and releases two hypothalamic peptides delivered down the hypothalamic-hypophyseal tract: antidiuretic hormone (ADH) from the supraoptic nuclei and oxytocin from the paraventricular nuclei. Destroying these axon terminals eliminates ADH, so the kidney tubules cannot reabsorb water (diabetes insipidus, producing dilute copious urine), and eliminates oxytocin, so the milk-ejection (let-down) reflex fails; both effects are the direct result. (Choice C) is correct: ADH loss impairs renal water reabsorption and oxytocin loss abolishes milk let-down, and both hormones are stored/released by the injured posterior lobe. (Choice B) is incorrect: cortisol and thyroid hormone depend on ACTH and TSH, which are manufactured by the anterior pituitary; since that lobe is explicitly spared, these axes remain intact. (Choice A) is incorrect: growth hormone and prolactin are also anterior pituitary products, so their release is preserved by an intact anterior lobe. (Choice D) is incorrect: aldosterone comes from the adrenal cortex (driven by the renin-angiotensin system) and epinephrine from the adrenal medulla; neither is a pituitary hormone, so a pituitary lesion does not directly abolish them. This item rewards Skill 2 reasoning: the student must map the anatomical site of injury onto the specific hormones each pituitary lobe handles and then translate the resulting hormone loss into its physiological deficits.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
